var n=`0661-akara`;var t=`world-0661`;var a=`NG`;var s=`western-africa`;var o=8;var r=527;var d={en:`Akara`,ua:`Акара`};var l={en:`Akara is a Nigeria classic prepared with black-eyed peas, yellow onion, scotch bonnet pepper, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Акара, страва кухні країни Нігерія зі складниками: квасоля чорноочка, жовта цибуля, перець скотч-боннет, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`black-eyed-peas`,430,`g`],[`water`,850,`ml`]]},{en:`Blend drained soaked peas with onion and chili, then season; the paste must be thick enough to hold a spoonful.`,ua:`Збийте замочений обсушений горох із цибулею та чилі; маса має бути достатньо густою, щоб триматися на ложці.`,t:[`mixing`],m:15,i:[[`yellow-onion`,170,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`water`,130,`ml`],[`table-salt`,5,`g`]]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:7,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 22 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 22 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:22,i:[[`sunflower-oil`,800,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`tomato`,160,`g`]]}];var g={slug:n,id:t,country:`NG`,region:s,servings:8,minutes:527,title:d,text:l,steps:h};export{a as country,g as default,t as id,r as minutes,s as region,o as servings,n as slug,h as steps,l as text,d as title};